questions.starter:
function rule(selector, property, value) {
  // return css
}

questions.solution:
function rule(selector, property, value) {
  return selector + ' { ' + property + ': ' + value + '; }';
}

questions.starter:
function idRule(id, property, value) {
  // return css
}

questions.solution:
function idRule(id, property, value) {
  return '#' + id + ' { ' + property + ': ' + value + '; }';
}
